package gadomancymodern.test;
import gadomancymodern.Gadomancy;
import gadomancymodern.node.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.properties.SlabType;
import net.minecraft.world.phys.*;
import net.minecraftforge.gametest.*;
import tc4revival.aspect.*;
import tc4revival.content.*;
@GameTestHolder("gadomancy") @PrefixGameTestTemplate(false)
public class NodeServerTests {
    public static net.minecraftforge.common.util.FakePlayer player(GameTestHelper test){var p=new net.minecraftforge.common.util.FakePlayer(test.getLevel(),new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"GadNode"));p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);return p;}
    public static BlockPos structure(GameTestHelper test,boolean portal){var level=test.getLevel();var at=test.absolutePos(new BlockPos(5,5,5));level.setBlockAndUpdate(at,Gadomancy.MANIPULATOR.get().defaultBlockState());level.setBlockAndUpdate(at.above(),(portal?Gadomancy.PORTAL_FOCUS:Gadomancy.RANDOMIZATION_FOCUS).get().defaultBlockState());level.setBlockAndUpdate(at.above(2),TCArcane.AURA_NODE.get().defaultBlockState());((AuraNodeBlockEntity)level.getBlockEntity(at.above(2))).configure(new AspectAmounts().add(TCAspects.catalog().require("aer"),25).add(TCAspects.catalog().require("ignis"),15),AuraNodeType.NORMAL,null,"gad-test",false);for(int x:new int[]{-1,1})for(int z:new int[]{-1,1}){level.setBlockAndUpdate(at.offset(x,0,z),TCEldritch.PEDESTAL_STONE.get().defaultBlockState());level.setBlockAndUpdate(at.offset(x,1,z),TCEldritch.STONE.get().defaultBlockState());}if(portal)for(var d:Direction.Plane.HORIZONTAL){var pos=at.relative(d,3);level.setBlockAndUpdate(pos,Gadomancy.ANCIENT_PEDESTAL.get().defaultBlockState());((gadomancymodern.compressor.AncientPedestalEntity)level.getBlockEntity(pos)).setItem(0,new ItemStack(TCEldritch.ELDRITCH_EYE.get()));}return at;}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void formationBufferMutationAndBreakPreserveOriginalCosts(GameTestHelper test){var level=test.getLevel();var at=structure(test,false);var tile=(NodeManipulatorEntity)level.getBlockEntity(at);var p=player(test);var wand=TCItems.CASTING_WAND.get().create(WandParts.Rod.SILVERWOOD_STAFF,WandParts.Cap.GOLD,false,true);p.setItemInHand(InteractionHand.MAIN_HAND,wand);test.assertTrue(!tile.form(p,InteractionHand.MAIN_HAND),"Node manipulator needs research");thaumcraft.api.ThaumcraftApiHelper.completeResearch(p,"gadomancy:node_manipulator");var air=TCAspects.catalog().require("aer");int before=TCItems.CASTING_WAND.get().vis(wand,air);test.assertTrue(tile.form(p,InteractionHand.MAIN_HAND),"Exact four pillar pattern forms");test.assertTrue(before-TCItems.CASTING_WAND.get().vis(wand,air)==10000,"Formation takes original 100 vis each");tile.setItem(0,wand);test.assertTrue(tile.drain()&&tile.work.total()==1,"One shuffled primal drains one vis per tick");for(var a:TCAspects.catalog().primals())tile.work.add(a,70-tile.work.amount(a));tile.removeItemNoUpdate(0);tile.tick();test.assertTrue(tile.working,"Work begins only once wand no longer drains");for(int i=0;i<299;i++)tile.tick();test.assertTrue(tile.workTick==299&&tile.working,"Mutation waits the whole 300 ticks");tile.tick();test.assertTrue(!tile.working&&tile.work.isEmpty()&&level.getBlockEntity(at.above(2)) instanceof AuraNodeBlockEntity,"Mutation completes and spends all buffered vis");tile.setItem(0,wand);var saved=tile.saveWithoutMetadata();var restored=new NodeManipulatorEntity(at,tile.getBlockState());restored.load(saved);test.assertTrue(restored.formed&&ItemStack.isSameItemSameTags(restored.getItem(0),wand),"Formation and held wand survive persistence");tile.breakStructure();test.assertTrue(level.getBlockState(at.offset(1,0,1)).is(TCEldritch.PEDESTAL_STONE.get())&&tile.isEmpty(),"Dismantling restores old stone and releases wand");test.succeed();}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void portalCraftConsumesFourEyesAndOnlyFinishesAtFourHundred(GameTestHelper test){var at=structure(test,true);var level=test.getLevel();var tile=(NodeManipulatorEntity)level.getBlockEntity(at);var p=player(test);var wand=TCItems.CASTING_WAND.get().create(WandParts.Rod.SILVERWOOD_STAFF,WandParts.Cap.GOLD,false,true);p.setItemInHand(InteractionHand.MAIN_HAND,wand);thaumcraft.api.ThaumcraftApiHelper.completeResearch(p,"gadomancy:e_portal_creator");test.assertTrue(tile.form(p,InteractionHand.MAIN_HAND),"Portal structure forms with surrounding four pedestals");for(var a:TCAspects.catalog().primals())tile.work.add(a,120);tile.tick();for(int i=0;i<399;i++)tile.tick();test.assertTrue(level.getBlockEntity(at.above(2)) instanceof AuraNodeBlockEntity&&tile.workTick==399,"Portal requires complete 400 tick cycle");tile.tick();test.assertTrue(level.getBlockState(at.above(2)).is(Gadomancy.ADDITIONAL_PORTAL.get()),"Real additional portal replaces node");for(var d:Direction.Plane.HORIZONTAL)test.assertTrue(((gadomancymodern.compressor.AncientPedestalEntity)level.getBlockEntity(at.relative(d,3))).isEmpty(),"Exactly one eldritch eye consumed from each pedestal");tile.tick();test.assertTrue(!tile.formed,"Node replacement dismantles the spent structure");test.succeed();}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void growingNodeFeedsPullsAndDoesNotOverflowCapacity(GameTestHelper test){var level=test.getLevel();var pos=test.absolutePos(new BlockPos(4,40,4));level.setBlockAndUpdate(pos,Gadomancy.EXTENDED_NODE.get().defaultBlockState());var node=(ExtendedNodeEntity)level.getBlockEntity(pos);var aspect=TCAspects.catalog().require("aer");node.configure(new AspectAmounts().add(aspect,10),AuraNodeType.NORMAL,null,"growth-test",false);node.extension="gadomancy:growing";var orb=new AspectOrbEntity(level,pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5,aspect,1);level.addFreshEntity(orb);node.tick();test.assertTrue(!orb.isAlive()&&node.permanentBase().amount(aspect)==11&&node.growth.saturation.containsKey("aer"),"Physical aspect orb grows permanent capacity");var saved=node.saveWithoutMetadata();var restore=new ExtendedNodeEntity(pos,node.getBlockState());restore.load(saved);test.assertTrue(restore.growing()&&restore.growth.saturation.get("aer").equals(node.growth.saturation.get("aer")),"Extension and original saturation persist");var far=new AspectOrbEntity(level,pos.getX()+5.5,pos.getY()+.5,pos.getZ()+.5,aspect,1);far.setDeltaMovement(Vec3.ZERO);level.addFreshEntity(far);node.tick();test.assertTrue(far.getDeltaMovement().x<0,"Nearby essence is physically pulled toward the node");far.discard();node.configure(new AspectAmounts().add(aspect,1000000),AuraNodeType.NORMAL,null,"large-node",false);var limit=new AspectOrbEntity(level,pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5,aspect,1);level.addFreshEntity(limit);node.tick();test.assertTrue(node.permanentBase().amount(aspect)==1000000&&!limit.isAlive(),"Extreme command-created nodes consume food without crashing capacity limit");level.removeBlock(pos,false);test.succeed();}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void growingNodeJarCaptureItemPlacementAndReleaseKeepExtraData(GameTestHelper test){var level=test.getLevel();var origin=test.absolutePos(new BlockPos(2,20,2));var center=origin.offset(1,0,1);for(int row=0;row<4;row++)for(int x=0;x<3;x++)for(int z=0;z<3;z++)level.setBlock(origin.offset(x,2-row,z),row==0?Blocks.OAK_SLAB.defaultBlockState().setValue(SlabBlock.TYPE,SlabType.BOTTOM):Blocks.GLASS.defaultBlockState(),18);level.setBlock(center,Gadomancy.EXTENDED_NODE.get().defaultBlockState(),18);var node=(ExtendedNodeEntity)level.getBlockEntity(center);var aspect=TCAspects.catalog().require("ignis");node.configure(new AspectAmounts().add(aspect,36),AuraNodeType.NORMAL,null,"jar-growing",false);node.extension="gadomancy:growing";node.growth.saturation.put("ignis",27d);var player=player(test);thaumcraft.api.ThaumcraftApiHelper.completeResearch(player,"NODEJAR");var wand=TCItems.CASTING_WAND.get().create(WandParts.Rod.SILVERWOOD_STAFF,WandParts.Cap.GOLD,false,true);player.setItemInHand(InteractionHand.MAIN_HAND,wand);var context=new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(origin.getCenter(),Direction.UP,origin,false));test.assertTrue(NodeJarCapture.form(wand,context).consumesAction()&&level.getBlockEntity(center) instanceof ExtendedNodeJarEntity,"Core transaction invokes addon jar capture extension");var jar=(ExtendedNodeJarEntity)level.getBlockEntity(center);var stack=jar.asItem();test.assertTrue(stack.is(Gadomancy.EXTENDED_JAR_ITEM.get())&&stack.getTag().getCompound("Gadomancy").getCompound("Growth").getCompound("Saturation").getDouble("ignis")==27,"Dropped jar item preserves exact growing saturation");var restored=new ExtendedNodeJarEntity(center,jar.getBlockState());restored.load(jar.saveWithoutMetadata());test.assertTrue(restored.contents().aspects().amount(aspect)==36&&restored.extension.equals(jar.extension),"Jar block entity survives save/load");var release=new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(center.getCenter(),Direction.UP,center,false));test.assertTrue(jar.onWandUseFirst(wand,release).consumesAction()&&level.getBlockEntity(center) instanceof ExtendedNodeEntity,"Wand release restores extended node type");var grown=(ExtendedNodeEntity)level.getBlockEntity(center);test.assertTrue(grown.growing()&&grown.growth.saturation.get("ignis")==27,"Growing behavior survives complete capture/release");level.removeBlock(center,false);test.succeed();}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void originalCreativeNodeVariantsPlaceAndDoNotConsume(GameTestHelper test){var level=test.getLevel();var player=player(test);int i=0;for(var stack:gadomancymodern.item.CreativeNodeItem.variants(Gadomancy.CREATIVE_NODE.get())){var at=test.absolutePos(new BlockPos(2+i*2,60,2));level.setBlockAndUpdate(at,Blocks.STONE.defaultBlockState());level.removeBlock(at.above(),false);player.setItemInHand(InteractionHand.MAIN_HAND,stack);var result=stack.getItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(at.getCenter(),Direction.UP,at,false)));test.assertTrue(result.consumesAction()&&stack.getCount()==1,"Original creative tool places without consuming");var node=(AuraNodeBlockEntity)level.getBlockEntity(at.above());test.assertTrue(node.nodeType()==AuraNodeType.values()[i],"Every original node type remains selectable");if(i==0)test.assertTrue(node.nodeModifier()==AuraNodeModifier.BRIGHT&&node.aspects().size()==6&&node.aspects().view().values().stream().allMatch(n->n==500),"Normal variant creates six-primal 500-vis bright node");level.removeBlock(at.above(),false);i++;}test.assertTrue(i==6,"Six original author creative entries");test.succeed();}
}
